/**
 * Switch. A molded cap thumb in a deep recessed track (the Field's well),
 * lit in the accent when on. The thumb is a fixed-size
 * block that only translates — never resizes — so the knob can't morph on toggle.
 * Composes var(--echo-*).
 */
.echo-switch {
  position: relative;
  display: inline-block;
  box-sizing: border-box;
  width: 48px;
  height: 24px;
  padding: var(--echo-space-2);
  border: 0;
  border-radius: var(--echo-radius-full);
  cursor: pointer;
  /* Deep recessed well — same near-black recipe as the Field. */
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  );
  box-shadow: var(
    --echo-shadow-well,
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)))
  );
  /* How lit the track is, 0–1. The state sets it; while the knob is thrown
     or dragged, switch.tsx writes it from the knob's position, so the colour
     fills in behind the knob. */
  --p: 0;
}

.echo-switch[data-checked] {
  --p: 1;
}

.echo-switch::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(180deg, var(--echo-accent-4) 0%, var(--echo-accent-5) 100%);
  opacity: var(--p);
  pointer-events: none;
}

.echo-switch:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}

.echo-switch:disabled {
  opacity: 0.45;
  cursor: default;
}

/* Molded buttonCap thumb (reference material.buttonCap, 4 stops). Fixed size —
   only `transform` animates, so the knob never changes shape on toggle. */
.echo-switch__thumb {
  /* Above the lit layer. */
  position: relative;
  z-index: var(--echo-z-raised, 1);
  display: block;
  box-sizing: border-box;
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  border-radius: var(--echo-radius-full);
  background: linear-gradient(
    180deg,
    var(--echo-cap-highlight) 0%,
    color-mix(in oklab, var(--echo-cap-highlight) 50%, var(--echo-cap)) 40%,
    var(--echo-cap) 62%,
    var(--echo-cap-shadow) 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.4 * var(--echo-gloss, 1))),
    0 calc(2px + 4px * var(--lift, 0)) calc(4px + 7px * var(--lift, 0))
      color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent);
  will-change: transform;
}

/*
 * Travel = inner width (48 − 6) − thumb (18) = 24px. The resting position is a
 * logical margin, which switch.tsx never touches and which follows the
 * writing direction by itself; the throw across is GSAP on `transform`. Not
 * the `translate` property: GSAP folds that into its own transform on the
 * first tween and resets it to none, which parked the knob at "off".
 */
.echo-switch[data-checked] .echo-switch__thumb {
  margin-inline-start: 24px;
}



/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the 44px both
 * platform guidelines use — a fingertip rather than conformance. Gated on
 * `@media (pointer: coarse)`, so the desktop rendering does not move.
 *
 * Where a control's visual size is the design (a 24px checkbox, a 10px pip),
 * the target is grown with the same transparent pseudo-element as the 24px minimum,
 * not by growing the control.
 */
@media (pointer: coarse) {
  .echo-switch {
    --echo-hit-area: 44px;
    position: relative;
  }

  .echo-switch::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: max(100%, 44px);
    height: max(100%, 44px);
    transform: translate(-50%, -50%);
  }
}

/*
 * Forced colors (Windows High Contrast) drops gradients and shadows, which is
 * everything that draws this control's state. System colors draw it instead;
 * nothing here sets forced-color-adjust: none, so focus outlines still show.
 */
@media (forced-colors: active) {
  .echo-switch::before {
    display: none;
  }
  .echo-switch {
    background: Canvas;
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
  .echo-switch[data-checked] {
    background: Highlight;
    border-color: Highlight;
  }
  .echo-switch__thumb {
    background: ButtonText;
  }
  .echo-switch[data-checked] .echo-switch__thumb {
    background: HighlightText;
  }
}

"use client";

/**
 * Switch. Base UI Switch behavior (role=switch,
 * keyboard, a11y) with a hardware-toggle skin and a click sound on toggle.
 *
 * Sound is driven from onCheckedChange rather than useTactile: Base UI's Root
 * owns the click handler, so wrapping the change callback avoids clobbering it.
 *
 * The knob has mass, and it keeps its shape. Hovered, it pops up out of the
 * track; held, it grows and lifts clear. It can be dragged: it follows the
 * finger along the track, the colour filling in behind it, rubber-banding
 * past the ends — let go past halfway and the switch flips, short of it and
 * the knob springs home. A click throws it across on a spring. The state
 * flips at once either way; only the knob and the light catch up.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import { Switch as BaseSwitch } from "@base-ui/react/switch";
import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  type MutableRefObject,
  type PointerEvent,
} from "react";
import gsap from "gsap";
import type { EchoChangeEvent, EchoInterop } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { springs } from "echo-ui-core/motion";
import {
  createSpring,
  rubberband,
  timing,
  useReducedMotionRef,
  watchTravel,
  type Spring,
} from "echo-ui-core/tactile";
import "./switch.css";

interface SwitchOwnProps extends EchoInterop {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean, eventDetails: EchoChangeEvent) => void;
}

/**
 * A control has to have a name: `aria-label`, or
 * `aria-labelledby` pointing at visible text. Leaving both out is a type
 * error, so it gets decided rather than forgotten.
 */
type AccessibleName =
  | { "aria-label": string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; "aria-label"?: string };

export type SwitchProps = SwitchOwnProps & AccessibleName;

/** `forwardRef`, not a `ref` prop — see the note on `Checkbox`. */
export const Switch = forwardRef<HTMLButtonElement, SwitchProps>(function Switch(
  { onCheckedChange, ...props },
  ref,
) {
  const sound = useSoundOptional();
  const reduced = useReducedMotionRef();
  const root = useRef<HTMLButtonElement | null>(null);
  const thumb = useRef<HTMLSpanElement | null>(null);
  const hovered = useRef(false);
  const held = useRef(false);
  // The knob's offset from where CSS puts it: the rest of a throw still to
  // travel, plus how far the finger has dragged it.
  const lag = useRef<Spring | null>(null);
  const drag = useRef<Spring | null>(null);
  const gesture = useRef<{ startX: number; moved: boolean; pointerId: number } | null>(null);
  const swallowClick = useRef(false);

  const setRoot = useCallback(
    (node: HTMLButtonElement | null) => {
      root.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<HTMLButtonElement | null>).current = node;
    },
    [ref],
  );

  /** +1 in left-to-right, -1 in right-to-left: which way "on" is. */
  const direction = () => (root.current && getComputedStyle(root.current).direction === "rtl" ? -1 : 1);

  useEffect(() => {
    const r = root.current;
    const t = thumb.current;
    if (!r || !t) return;
    // Draw the knob, and fill the track behind it: --p is how far toward
    // "on" the knob is, 0–1, so dragging it halfway lights the track halfway.
    const draw = () => {
      const x = (lag.current?.value ?? 0) + (drag.current?.value ?? 0);
      gsap.set(t, { x });
      const on = r.hasAttribute("data-checked") ? 1 : 0;
      const p = Math.min(1, Math.max(0, on + (x * direction()) / 24));
      r.style.setProperty("--p", p.toFixed(3));
    };
    lag.current = createSpring(0, springs.bouncy, draw);
    drag.current = createSpring(0, springs.bouncy, draw);
    const stop = watchTravel({
      part: t,
      frame: r,
      on: r,
      attributes: ["data-checked", "data-unchecked"],
      onMove: (dx) => {
        if (reduced.current || !lag.current) {
          draw();
          return;
        }
        lag.current.shift(dx);
        lag.current.to(0, { config: springs.bouncy });
      },
    });
    return () => {
      stop();
      lag.current?.stop();
      drag.current?.stop();
      gsap.killTweensOf(t);
    };
  }, [reduced]);

  /* The knob's pose. It never deforms: it pops up when hovered, and grows and
     lifts when held. */
  const pose = (name: "lift" | "rebound") => {
    const t = thumb.current;
    if (!t) return;
    const vars = { "--lift": held.current ? 1 : hovered.current ? 0.6 : 0 };
    if (reduced.current) {
      gsap.set(t, vars);
      return;
    }
    gsap.to(t, {
      ...timing(name),
      overwrite: "auto",
      ...vars,
      scale: held.current ? 1.22 : hovered.current ? 1.12 : 1,
    });
  };

  const release = (e: PointerEvent<HTMLElement>) => {
    const g = gesture.current;
    gesture.current = null;
    if (held.current) {
      held.current = false;
      pose("rebound");
    }
    if (!g || !drag.current) return;
    if (e.currentTarget.hasPointerCapture(g.pointerId)) e.currentTarget.releasePointerCapture(g.pointerId);
    if (!g.moved) return;
    // Past halfway (or flicked that way) the click that follows flips the
    // switch; short of it, the click is swallowed and the knob goes home.
    const on = e.currentTarget.hasAttribute("data-checked");
    const toward = (drag.current.value + drag.current.velocity * 0.08) * direction();
    const flips = on ? toward < -12 : toward > 12;
    swallowClick.current = !flips;
    drag.current.to(0, { config: springs.bouncy });
  };

  return (
    <BaseSwitch.Root
      ref={setRoot}
      className="echo-switch"
      onCheckedChange={(checked, eventDetails) => {
        sound?.play("tap");
        onCheckedChange?.(checked, eventDetails);
      }}
      onClickCapture={(e) => {
        if (!swallowClick.current) return;
        swallowClick.current = false;
        e.preventDefault();
        e.stopPropagation();
      }}
      onPointerEnter={(e) => {
        if (e.pointerType !== "mouse" || props.disabled) return;
        hovered.current = true;
        pose("lift");
      }}
      onPointerLeave={() => {
        hovered.current = false;
        if (!gesture.current) pose("rebound");
      }}
      onPointerDown={(e) => {
        if (e.button !== 0 || props.disabled) return;
        held.current = true;
        swallowClick.current = false;
        pose("lift");
        if (reduced.current) return;
        gesture.current = { startX: e.clientX, moved: false, pointerId: e.pointerId };
        e.currentTarget.setPointerCapture(e.pointerId);
      }}
      onPointerMove={(e) => {
        const g = gesture.current;
        if (!g || !drag.current) return;
        const dx = e.clientX - g.startX;
        if (Math.abs(dx) > 3) g.moved = true;
        if (!g.moved) return;
        // Free between the two ends; past either, it rubber-bands.
        const on = e.currentTarget.hasAttribute("data-checked");
        const d = direction();
        const lo = on ? -24 : 0;
        const hi = on ? 0 : 24;
        let x = dx * d;
        if (x < lo) x = lo + rubberband(x - lo, 8);
        if (x > hi) x = hi + rubberband(x - hi, 8);
        drag.current.to(x * d, { config: springs.track });
      }}
      onPointerUp={release}
      onPointerCancel={release}
      {...props}
    >
      <BaseSwitch.Thumb ref={thumb} className="echo-switch__thumb" />
    </BaseSwitch.Root>
  );
});
